               animate={{ opacity: 1, x: 0 }}
               className="px-6 py-2.5 rounded-2xl bg-blue-500/10 border border-blue-500/20 flex items-center gap-3 shadow-[0_0_20px_rgba(59,130,246,0.1)] relative group"
