  const baseStyles = 'backdrop-blur-xl bg-white/5 border border-white/10';
  
  const variants = {
    default: '',
    elevated: 'shadow-2xl',
    interactive: 'cursor-pointer hover:bg-white/10 hover:border-white/20 transition-all duration-300'
  };

  const paddings = {
    sm: 'p-4',
    md: 'p-6',
    lg: 'p-8'
  };

  const roundings = {
    md: 'rounded-xl',
    lg: 'rounded-2xl',
    xl: 'rounded-3xl',
    '2xl': 'rounded-3xl',
