  };

  return (
    <motion.div
      whileHover={variant === 'interactive' ? { y: -4, scale: 1.02 } : {}}
      className={`
        ${baseStyles}
        ${variants[variant]}
        ${paddings[padding]}
        ${roundings[rounded]}
