          `}
          {...props}
        />

        {/* Dynamic Glow Effect */}
        <div className="absolute -inset-px rounded-2xl bg-gradient-to-r from-blue-500/20 to-purple-500/20 opacity-0 group-focus-within:opacity-100 blur-sm -z-10 transition-opacity duration-500" />
        
        {error && (
          <motion.p
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="absolute -bottom-6 left-1 text-[10px] font-bold uppercase tracking-widest text-red-400"
          >
            {error}
          </motion.p>
        )}
      </div>
    </div>
  );
}

import { motion } from 'framer-motion';

export function GlowingIcon({ children, color = 'purple', className = '' }) {
  const colors = {
    purple: '#667eea',
    blue: '#3b82f6',
    green: '#10b981',
    red: '#ef4444',
    yellow: '#f59e0b',
    white: '#ffffff'
  };

  const selectedColor = colors[color] || colors.purple;

  return (
    <motion.div
      animate={{
        filter: [
          `drop-shadow(0 0 10px ${selectedColor}80)`,
          `drop-shadow(0 0 20px ${selectedColor}CC)`,
          `drop-shadow(0 0 10px ${selectedColor}80)`
        ]
      }}
      transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
      className={`text-4xl ${className}`}
    >
      {children}
    </motion.div>
  );
}

